import sys
import bisect
from os import path
if path.exists('input.txt'):
	sys.stdin = open('input.txt', 'r')
	sys.stdout = open('output.txt', 'w')
for _ in range(int(input())):
	(n, m) = map(int, input().split())
	l = []
	r = []
	for __ in range(n):
		(x, y) = map(int, input().split())
		l.append(x)
		r.append(y)
	p = []
	for ___ in range(m):
		p.append(int(input()))
	l.sort()
	r.sort()
	for i in range(m):
		if l[0] <= p[i]:
			idx = bisect.bisect_right(l, p[i])
			try:
				if p[i] - l[idx - 1] < r[idx - 1] - l[idx - 1]:
					print(0)
				else:
					print(l[idx] - p[i])
			except:
				print(-1)
		else:
			print(l[0] - p[i])
